INSERT INTO prompts (id, title, category, role, tags, access, prompt_body) SELECT id, title, 'Banking & Fintech Engagement', 'a senior banking and fintech customer-engagement strategist', tags, access, CONCAT('ROLE: You are a senior banking and fintech customer-engagement strategist with expertise in ', LOWER(tags), '.\n\nTASK: Create a production-ready ', LOWER(title), ' for [specific use-case] and [campaign goal].\n\nAUDIENCE: [target customer segment] with documented consent where required.\n\nPLATFORM / FORMAT: [preferred channel or format].\n\nTONE / VOICE: Clear, reassuring, inclusive, concise, and useful.\n\nPRIMARY GOAL: [campaign goal].\n\nDELIVERABLES:\n1. A ready-to-use sequence, brief, or engagement asset with clear variables.\n2. Personalization logic for [customer segment] and [customer stage].\n3. Timing, CTA, measurement, and human hand-off recommendations.\n4. Channel-specific copy for the tagged channels.\n5. Compliance review notes and an approval checklist.\n\nCONSTRAINTS: Use only consented outreach, minimize personal data, mask identifiers, never request full card numbers, PINs, PANs, or passwords, avoid guaranteed outcomes, include opt-out and HELP handling, use secure authenticated links for sensitive actions, and provide human escalation.') FROM (SELECT '3218' AS id, 'First transaction activation flow' AS title, 'Onboarding, WhatsApp, Fintech' AS tags, 'LOCKED' AS access UNION ALL SELECT '3219' AS id, 'Card delivery update sequence' AS title, 'Operations, SMS, Banking' AS tags, 'LOCKED' AS access UNION ALL SELECT '3220' AS id, 'Account opening nurture series' AS title, 'Onboarding, Marcom, Banking' AS tags, 'LOCKED' AS access UNION ALL SELECT '3221' AS id, 'Digital banking feature launch' AS title, 'Product Marketing, AI Video, Banking' AS tags, 'LOCKED' AS access UNION ALL SELECT '3222' AS id, 'Financial literacy Reels brief' AS title, 'AI Video, Marcom, Banking' AS tags, 'LOCKED' AS access UNION ALL SELECT '3223' AS id, 'Festive savings creative brief' AS title, 'AI Video, Marcom, Banking' AS tags, 'LOCKED' AS access UNION ALL SELECT '3224' AS id, 'Credit score education campaign' AS title, 'Education, SMS, Fintech' AS tags, 'LOCKED' AS access UNION ALL SELECT '3225' AS id, 'Buy now pay later onboarding' AS title, 'Lending, WhatsApp, Fintech' AS tags, 'LOCKED' AS access UNION ALL SELECT '3226' AS id, 'Merchant settlement notification flow' AS title, 'Payments, SMS, Fintech' AS tags, 'LOCKED' AS access UNION ALL SELECT '3227' AS id, 'Wallet funding reminder sequence' AS title, 'Payments, WhatsApp, Fintech' AS tags, 'LOCKED' AS access UNION ALL SELECT '3228' AS id, 'Failed payment recovery journey' AS title, 'Payments, Automation, Banking' AS tags, 'LOCKED' AS access UNION ALL SELECT '3229' AS id, 'Chargeback status communications' AS title, 'Operations, SMS, Banking' AS tags, 'LOCKED' AS access UNION ALL SELECT '3230' AS id, 'Subscription payment reminder pack' AS title, 'Payments, SMS, Fintech' AS tags, 'LOCKED' AS access UNION ALL SELECT '3231' AS id, 'Customer NPS engagement plan' AS title, 'Retention, Marcom, Banking' AS tags, 'LOCKED' AS access UNION ALL SELECT '3232' AS id, 'Complaint resolution update flow' AS title, 'Customer Service, WhatsApp, Banking' AS tags, 'LOCKED' AS access UNION ALL SELECT '3233' AS id, 'Branch appointment reminder flow' AS title, 'Operations, SMS, Banking' AS tags, 'LOCKED' AS access UNION ALL SELECT '3234' AS id, 'Relationship manager hand-off flow' AS title, 'Customer Service, WhatsApp, Banking' AS tags, 'LOCKED' AS access UNION ALL SELECT '3235' AS id, 'High-value customer education plan' AS title, 'Marcom, Banking, Fintech' AS tags, 'LOCKED' AS access UNION ALL SELECT '3236' AS id, 'Microfinance onboarding sequence' AS title, 'Onboarding, SMS, Fintech' AS tags, 'LOCKED' AS access UNION ALL SELECT '3237' AS id, 'Insurance add-on engagement plan' AS title, 'Cross-sell, WhatsApp, Banking' AS tags, 'LOCKED' AS access UNION ALL SELECT '3238' AS id, 'Investment education campaign' AS title, 'Education, AI Video, Banking' AS tags, 'LOCKED' AS access UNION ALL SELECT '3239' AS id, 'Remittance transaction update flow' AS title, 'Payments, WhatsApp, Banking' AS tags, 'LOCKED' AS access) AS batch ON DUPLICATE KEY UPDATE title=VALUES(title), category=VALUES(category), role=VALUES(role), tags=VALUES(tags), access=VALUES(access), prompt_body=VALUES(prompt_body);\n